"""
Train Machine Learning Models for Protein Function Prediction
Generates validated scikit-learn models for:
1. Enzyme vs Non-Enzyme Classification
2. Enzyme Commission (EC) Main Class Prediction (EC 1 to EC 7)
3. Subcellular Localization Prediction (Cytoplasm, Nucleus, Extracellular, Mitochondria, Membrane)

Uses sequence-derived physicochemical descriptors:
- 20 Amino Acid Composition (AAC) fractions
- 6 Biochemical group ratios
- Molecular weight per residue, Isoelectric Point (pI), Net Charge at pH 7
- GRAVY hydropathicity index, Instability index, Aliphatic index
- Chou-Fasman secondary structure propensities
"""

import os
import joblib
import numpy as np
from sklearn.ensemble import RandomForestClassifier, GradientBoostingClassifier
from sklearn.model_selection import cross_val_score, StratifiedKFold
from sklearn.preprocessing import StandardScaler

from bio_analysis.validator import STANDARD_AMINO_ACIDS
from bio_analysis.physicochemical import (
    analyze_physicochemical_properties,
    RESIDUE_WEIGHTS,
    compute_isoelectric_point,
    calculate_net_charge,
    compute_gravy,
    compute_instability_index,
    compute_aliphatic_index,
    compute_secondary_structure_propensities
)

FEATURE_NAMES = [
    'AAC_A', 'AAC_C', 'AAC_D', 'AAC_E', 'AAC_F',
    'AAC_G', 'AAC_H', 'AAC_I', 'AAC_K', 'AAC_L',
    'AAC_M', 'AAC_N', 'AAC_P', 'AAC_Q', 'AAC_R',
    'AAC_S', 'AAC_T', 'AAC_V', 'AAC_W', 'AAC_Y',
    'ratio_hydrophobic', 'ratio_aromatic', 'ratio_polar',
    'ratio_basic', 'ratio_acidic', 'ratio_special',
    'mw_per_residue', 'isoelectric_point', 'charge_density_ph7',
    'gravy', 'instability_index', 'aliphatic_index',
    'helix_fraction', 'sheet_fraction', 'turn_fraction'
]


def extract_features(sequence: str) -> np.ndarray:
    """Extracts 35-dimensional numerical feature vector from amino acid sequence."""
    length = max(1, len(sequence))
    
    # 20 AAC
    aac = [sequence.count(aa) / length for aa in sorted(STANDARD_AMINO_ACIDS)]
    
    # Biochemical ratios
    r_hydrophobic = sum(sequence.count(aa) for aa in 'AVILM') / length
    r_aromatic = sum(sequence.count(aa) for aa in 'FWY') / length
    r_polar = sum(sequence.count(aa) for aa in 'STNQ') / length
    r_basic = sum(sequence.count(aa) for aa in 'KRH') / length
    r_acidic = sum(sequence.count(aa) for aa in 'DE') / length
    r_special = sum(sequence.count(aa) for aa in 'GPC') / length
    
    # Physicochemical properties
    mw = sum(RESIDUE_WEIGHTS.get(aa, 110.0) for aa in sequence) + 18.015
    mw_per_res = mw / length
    pi = compute_isoelectric_point(sequence)
    charge_density = calculate_net_charge(sequence, 7.0) / length
    gravy = compute_gravy(sequence)
    instab, _ = compute_instability_index(sequence)
    aliph = compute_aliphatic_index(sequence)
    sec = compute_secondary_structure_propensities(sequence)
    
    feats = aac + [
        r_hydrophobic, r_aromatic, r_polar, r_basic, r_acidic, r_special,
        mw_per_res, pi, charge_density, gravy, instab, aliph,
        sec['helix_fraction'], sec['sheet_fraction'], sec['turn_fraction']
    ]
    return np.array(feats, dtype=np.float32)


