def train_and_export_models(output_dir: str = "models"):
    """Trains Random Forest classifiers and exports serialized joblib models."""
    os.makedirs(output_dir, exist_ok=True)
    print("Extracting features from benchmark dataset...")

    X = []
    y_enzyme = []
    y_ec = []
    y_loc = []

    for seq, is_enz, ec, loc in BENCHMARK_DATA:
        feats = extract_features(seq)
        X.append(feats)
        y_enzyme.append(is_enz)
        y_ec.append(ec)
        y_loc.append(loc)

    X = np.array(X, dtype=np.float32)
    y_enzyme = np.array(y_enzyme, dtype=np.int32)
    y_ec = np.array(y_ec, dtype=np.int32)
    y_loc = np.array(y_loc, dtype=np.int32)

    # 1. Enzyme Classifier
    print("Training Enzyme Classifier...")
    clf_enzyme = RandomForestClassifier(n_estimators=100, max_depth=8, random_state=42)
    clf_enzyme.fit(X, y_enzyme)
    cv_enzyme = cross_val_score(clf_enzyme, X, y_enzyme, cv=3).mean()
    print(f"Enzyme classifier 3-fold CV accuracy: {cv_enzyme:.3f}")

    # 2. EC Class Classifier (on enzymes)
    print("Training EC Class Classifier...")
    clf_ec = RandomForestClassifier(n_estimators=100, max_depth=6, random_state=42)
    clf_ec.fit(X, y_ec)

    # 3. Subcellular Localization Classifier
    print("Training Subcellular Localization Classifier...")
    clf_loc = RandomForestClassifier(n_estimators=100, max_depth=8, random_state=42)
    clf_loc.fit(X, y_loc)
    cv_loc = cross_val_score(clf_loc, X, y_loc, cv=3).mean()
    print(f"Localization classifier 3-fold CV accuracy: {cv_loc:.3f}")

    # Save models and metadata
    model_bundle = {
        'model_enzyme': clf_enzyme,
        'model_ec': clf_ec,
        'model_loc': clf_loc,
        'feature_names': FEATURE_NAMES,
        'metrics': {
            'enzyme_cv_accuracy': float(cv_enzyme),
            'loc_cv_accuracy': float(cv_loc),
            'n_samples': len(BENCHMARK_DATA),
            'n_features': len(FEATURE_NAMES)
        }
    }

    model_path = os.path.join(output_dir, "protein_function_models.joblib")
    joblib.dump(model_bundle, model_path)
    print(f"Model bundle successfully exported to: {model_path}")
    return model_bundle


if __name__ == "__main__":
    train_and_export_models()
